// Shell visual baselines (#11): every viewport × theme project (360/768/1280, light and dark) with
// the clock frozen; the sidebar expanded and collapsed (768 and 1280), the palette open and the
// switcher open (plus the More sheet on phones). Baselines live in e2e/__screenshots__ and are only
// ever generated by the e2e workflow's `update_snapshots` dispatch in the pinned Playwright image
// (see e2e/README.md); without one the test is skipped.
import { existsSync } from 'node:fs';

import type { Page, TestInfo } from '@playwright/test';

import { expect, test } from '../../fixtures/index.ts';

import {
  layoutOf,
  openShell,
  palette,
  shellRoot,
  sidebar,
  switcherList,
  switcherTrigger,
  type Layout,
} from './helpers.ts';

function skipWithoutBaseline(testInfo: TestInfo, name: string) {
  const baseline = testInfo.snapshotPath(name, { kind: 'screenshot' });
  test.skip(
    testInfo.config.updateSnapshots === 'none' && !existsSync(baseline),
    'no baseline yet: dispatch the e2e workflow with update_snapshots',
  );
}

async function snap(page: Page, name: string) {
  await expect(page).toHaveScreenshot(name, { animations: 'disabled', caret: 'hide' });
}

interface Shot {
  name: string;
  layouts: readonly Layout[];
  /** Puts the page in the state to capture, starting from the hydrated `/w/chennai-solo/today`. */
  setUp: (page: Page) => Promise<void>;
}

const ALL: readonly Layout[] = ['phone', 'rail', 'desktop'];

const SHOTS: readonly Shot[] = [
  { name: 'shell-today.png', layouts: ALL, setUp: async () => {} },
  {
    name: 'shell-sidebar-expanded.png',
    layouts: ['rail', 'desktop'],
    setUp: async (page) => {
      if (layoutOf(page) === 'rail') await page.keyboard.press('[');
      await expect(shellRoot(page)).toHaveAttribute('data-sidebar', /auto|expanded/);
      await expect.poll(async () => (await sidebar(page).boundingBox())?.width).toBe(264);
    },
  },
  {
    name: 'shell-sidebar-collapsed.png',
    layouts: ['rail', 'desktop'],
    setUp: async (page) => {
      if (layoutOf(page) === 'desktop') await page.keyboard.press('[');
      await expect.poll(async () => (await sidebar(page).boundingBox())?.width).toBe(64);
      // The toggle keeps focus after a click; the key press leaves none to paint.
    },
  },
  {
    name: 'shell-palette-open.png',
    layouts: ALL,
    setUp: async (page) => {
      await page.getByRole('banner').getByRole('button', { name: 'Open search' }).click();
      await expect(palette(page)).toBeVisible();
      await expect(palette(page).getByRole('option').first()).toBeVisible();
    },
  },
  {
    name: 'shell-switcher-open.png',
    layouts: ALL,
    setUp: async (page) => {
      await switcherTrigger(page).click();
      await expect(switcherList(page)).toBeVisible();
    },
  },
  {
    name: 'shell-more-sheet-open.png',
    layouts: ['phone'],
    setUp: async (page) => {
      await page.locator('[data-mobile-nav-item="more"]').click();
      await expect(page.getByRole('dialog', { name: 'More destinations' })).toBeVisible();
    },
  },
];

test.describe('shell visual baselines', () => {
  for (const shot of SHOTS) {
    test(
      shot.name.replace(/\.png$/, ''),
      { tag: '@visual' },
      async ({ page, asUser }, testInfo) => {
        test.skip(!shot.layouts.includes(layoutOf(page)), `not a ${layoutOf(page)} state`);
        skipWithoutBaseline(testInfo, shot.name);
        await openShell(page, asUser);
        await shot.setUp(page);
        await snap(page, shot.name);
      },
    );
  }
});
